"""Original bilingual synthetic frame-sampling lesson; no external data or runtime calls."""
from pathlib import Path


def render(root):
    for en in (False, True):
        def t(zh, english): return english if en else zh
        academy = 'academy-en.html' if en else 'academy.html'
        other = 'video-sampling-lab.html' if en else 'video-sampling-lab-en.html'
        title = t('视频抽帧实验：看见的，不等于连续的', 'Video sampling lab: observed is not continuous')
        def frames(name):
            items = []
            for i in range(9):
                identity = ('B' if name == 'worked' else 'C') if i == (3 if name == 'worked' else 5) else 'A'
                x = 10 + i * 10
                label = f'F{i} · {i * 250} ms · ID {identity} · x={x}'
                items.append(f'<li><svg viewBox="0 0 110 48" role="img" aria-label="{label}"><path d="M5 36 H105" stroke="#899eab"/><rect x="{x-5}" y="12" width="10" height="20" fill="#3f628f"/><text x="{x}" y="10" text-anchor="middle" font-size="10">{identity}</text></svg><span>{label}</span></li>')
            return '<ol class="frame-grid">'+''.join(items)+'</ol>'
        html = f'''<!doctype html><html lang="{'en' if en else 'zh-CN'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"><title>{title} · ModelAtlas</title><link rel="stylesheet" href="academy.css"><link rel="stylesheet" href="attention-lab.css"><link rel="stylesheet" href="video-sampling-lab.css"><script src="video-sampling.js" defer></script><script src="video-sampling-lab.js" defer></script></head><body class="academy-page"><main class="academy lab"><header><a href="{academy}#multimodal">← {t('返回多模态章','Back to multimodal')}</a><a href="{other}" lang="{'zh-CN' if en else 'en'}">{t('English','中文')}</a></header><p class="academy-eyebrow">MODELATLAS · {t('原创合成教学 / 时序证据','ORIGINAL SYNTHETIC LESSON / TEMPORAL EVIDENCE')}</p><h1>{title}</h1>
<p>{t('前置：能读时间戳，理解图像与视频输入的区别。产出：选择抽样间隔和起点，找到中间帧身份断点，写出“观察到了什么”和“尚不能证明什么”两部分证据报告。','Prerequisites: timestamps and the distinction between image and video inputs. Outcome: select a sampling stride and offset, locate a middle-frame identity discontinuity, and report both observed facts and what remains unproved.')}</p>
<p class="warning">{t('这里的九帧序列、身份标签与坐标由本站原创指定，不是模型生成的视频、真实跟踪结果或物理仿真。没有生成模型、API、VBench、真实基准测试、网络请求或学习记录存储。只演示有限抽样如何遗漏证据，不评判任何厂商。','The nine-frame sequences, identity labels and coordinates are original supplied fixtures—not model-generated video, real tracking results or a physics simulation. No generation model, API, VBench, real benchmark, network requests or progress storage. This demonstrates missed evidence under finite sampling, not vendor quality.')}</p>
<section><h2>1 · {t('机制：抽到哪些帧？','Mechanism: which frames are selected?')}</h2><p>{t('固定帧索引 i = 0…8，时间 t = 250i 毫秒，横坐标 x = 10 + 10i（教学单位）。每帧只有一个带身份标签的方块。起点 o 与间隔 s 选择 i = o + ks（k 为非负整数且 i ≤ 8）。这里 s 是帧数，不是秒；0 ≤ o < s。','Frame index i = 0…8, timestamp t = 250i milliseconds, position x = 10 + 10i in teaching units. Each frame contains one identity-labelled block. Offset o and stride s select i = o + ks for nonnegative integers k and i ≤ 8. Here s counts frames, not seconds; 0 ≤ o < s.')}</p><p>{t('身份一致性与位置平滑是两种检查。位置逐步增加不能证明对象身份没变。抽样没有发现变化，只说明所选帧未见变化；既不证明漏掉的帧，也不证明两个时间戳之间的连续运动。即使读完九帧，也不能推断未提供的中间时刻。','Identity consistency and smooth positions are different checks. Increasing positions do not prove stable identity. No observed change means only no change in the selected frames—not in omitted frames or between timestamps. Even all nine supplied frames cannot establish continuous motion at times not supplied.')}</p></section>
<section><h2>2 · {t('跟做：同样的首尾，不同的中间','Worked example: same endpoints, different middle')}</h2><p>{t('序列 W 的 F0 与 F8 都是 A。先用 s=4、o=0，选中 F0/F4/F8，身份全为 A，遗漏 F3（750 ms，B，x=40）。改成 s=4、o=3，选中 F3/F7，就能看到 B→A。再用 s=1、o=0，核对九帧：F2 的 A→F3 的 B→F4 的 A。位置仍然规则，身份却已断开。','Sequence W starts and ends with A. With s=4, o=0, F0/F4/F8 are all A; F3 (750 ms, B, x=40) is missed. With s=4, o=3, F3/F7 reveal B→A. Then s=1, o=0 inspects all nine frames: A at F2 → B at F3 → A at F4. Positions remain regular despite the identity discontinuity.')}</p><details><summary>{t('查看 W 全部原始帧（静态参考）','Inspect all W frames (static reference)')}</summary>{frames('worked')}</details></section>
<section><h2>3 · {t('亲手抽样','Sample the sequence')}</h2><div class="lab-controls"><label for="sequence">{t('序列','Sequence')}<select id="sequence"><option value="worked">{t('W · 跟做','W · Worked')}</option><option value="exercise">{t('E · 独立练习','E · Exercise')}</option></select></label><label for="stride">{t('间隔 s（帧）','Stride s (frames)')}<select id="stride">{''.join(f'<option value="{i}"'+(' selected' if i==4 else '')+f'>{i}</option>' for i in range(1,5))}</select></label><label for="offset">{t('起点 o','Offset o')}<select id="offset">{''.join(f'<option value="{i}">{i}</option>' for i in range(4))}</select></label><button id="reset" type="button">{t('重置全部','Reset all')}</button></div><noscript><p class="warning">{t('交互需要 JavaScript；原始帧、跟做和参考答案仍可阅读。可按公式在纸上完成抽样与报告，启用脚本后重载恢复交互。','Interaction needs JavaScript. Original frames, worked example and reference answer remain readable. Use the formula on paper to sample and write a report; enable scripts and reload for interaction.')}</p></noscript><p id="error" role="alert"></p><div id="result" hidden><p id="summary" role="status" aria-live="polite"></p><ol id="samples" class="frame-grid"></ol><p id="omitted"></p></div></section>
<section><h2>4 · {t('独立练习：找到另一个断点','Independent exercise: find another discontinuity')}</h2><p>{t('切换到 E。异常不在跟做的位置，标签也不同。先预测 s=4、o=0 能否发现身份变化，再改变 s 或 o 寻找证据。将当前序列设为 E，并保留能看见异常帧的抽样。选择异常索引及可支持的结论，生成证据报告。','Switch to E. The anomaly has a different location and label. Predict whether s=4, o=0 detects the change, then vary s or o to find evidence. Keep E selected with a sample that includes the anomalous frame. Choose its index and a supported conclusion to create an evidence report.')}</p><div class="lab-controls"><label for="answer">{t('异常帧索引','Anomalous frame index')}<select id="answer"><option value="">{t('请选择','Choose')}</option>{''.join(f'<option value="{i}">F{i}</option>' for i in range(9))}</select></label><label for="claim">{t('证据结论','Evidence conclusion')}<select id="claim"><option value="">{t('请选择','Choose')}</option><option value="limited">{t('看到变化，不证明连续性','Observed change; continuity unproved')}</option><option value="continuous">{t('首尾相同，所以全程一致','Same endpoints prove continuity')}</option></select></label><button id="check" type="button">{t('核对并生成报告','Check and create report')}</button></div><p id="feedback" role="status" aria-live="polite"></p><div id="report" hidden><h3>{t('本次证据报告','Evidence report for this attempt')}</h3><p id="report-facts"></p><p id="report-limits"></p></div>
<details><summary>{t('E 的完整帧与参考答案（先独立尝试）','All E frames and reference answer (try first)')}</summary>{frames('exercise')}<p>{t('答案：F5，1250 ms，身份 C，x=60；其他八帧是 A。s=4、o=0 抽到 F0/F4/F8，完全漏掉它。s=4、o=1 抽到 F1/F5，观察到 A→C；s=1、o=0 还能确认 F4/F5/F6 的 A→C→A。报告应写明选择规则、所选帧、遗漏帧、异常时间及身份；结论只覆盖给定帧。无法由本实验推出连续运动、物理正确性、真实模型质量或其他视频的表现。','Answer: F5, 1250 ms, identity C, x=60; the other eight frames are A. s=4, o=0 selects F0/F4/F8 and misses it entirely. s=4, o=1 selects F1/F5 and observes A→C. s=1, o=0 also confirms A→C→A at F4/F5/F6. Record the rule, selected and omitted frames, anomaly time and identity. Conclusions concern supplied frames only. Continuous motion, physical correctness, real model quality and other videos remain unproved.')}</p></details>
<p>{t('失败与恢复：空答案先补全；错选断点先检查完整帧；抽样遗漏则减小间隔或移动起点。改变实验或答案会清除旧报告，重新核对后才显示结果。切换语言仅通过链接片段保留合法配置和选项，绝不保留“通过”状态；须重新核对。重置恢复 W / s=4 / o=0 并清空答案。非法配置会清除结果，重置即可恢复。','Recovery: complete blank answers; inspect the full sequence after a wrong index; reduce stride or move the offset when evidence is omitted. Changing controls or answers clears the old report and requires another check. Language links carry only valid settings and choices in the fragment, never a passed state; check again. Reset restores W / s=4 / o=0 and clears answers. Invalid configurations clear results; reset to recover.')}</p></section>
<section><h2>5 · {t('迁移与边界','Transfer and limits')}</h2><p>{t('下一次面对真实视频，先说明目标属性（身份、位置或动作），时间覆盖与抽帧策略，再报告缺失区间；不能用“没抽到问题”替代“没有问题”。真实身份识别还会受遮挡、视角和识别误差影响；本课直接给定标签，未实现识别。下一步回到评测章，写清输入、测试条件、成功标准与未知项。','For a real video, first state the target property (identity, position or action), time coverage and sampling rule, then report gaps. “No problem sampled” is not “no problem exists.” Real identity recognition also faces occlusion, viewpoints and recognition errors; this lesson supplies labels and implements no recognition. Next, return to evaluation and specify inputs, test conditions, success criteria and unknowns.')}</p><p class="source">{t('来源与版本：原创合成教学数据 v1，2026-11-01；数学规则与全部参考帧在本页可查。不是论文复现，也没有外部测试数据。','Provenance and version: original synthetic teaching data v1, 2026-11-01. The sampling rule and all reference frames are inspectable here. Not a paper reproduction; no external test data.')}</p><p class="source">{t('延伸阅读：','Further reading: ')}<a href="https://arxiv.org/html/2311.17982v1">VBench · v1 · Temporal Flickering / Motion Smoothness / Human Action</a>. {t('首次提交 2023-11-29；CVPR 2024；来源核对 2026-11-01。该论文分开设计时序闪烁、运动平滑与动作识别等协议，不是一个通用抽帧规则。本课没有实现这些指标，也不提供任何通用安全间隔或帧率。','First submitted 2023-11-29; CVPR 2024; source checked 2026-11-01. The paper uses distinct protocols for temporal flickering, motion smoothness and action recognition, not one universal sampling rule. This lesson implements none of those metrics and establishes no universally safe stride or frame rate.')}</p><p><a href="video-sampling.js">{t('查看数据与抽样源码','Inspect fixture and sampling source')}</a> · <a href="{academy}#evaluation">{t('下一步：评测与方法','Next: Evaluation & Methods')} →</a></p></section></main></body></html>'''
        (root/'web'/('video-sampling-lab-en.html' if en else 'video-sampling-lab.html')).write_text(html)

if __name__ == '__main__': render(Path(__file__).resolve().parents[1])
